import manifest from '@/generated/image-manifest.json';

/**
 * @typedef {object} ImageEntry
 * @property {number} width     Intrinsic width of the original
 * @property {number} height    Intrinsic height of the original
 * @property {number[]} widths  Widths generated for srcset
 * @property {number} fallback  Width of the JPEG fallback
 */

const IMAGE_DIR = `${import.meta.env.BASE_URL}images`;

/**
 * Manifest entry for an image generated by `npm run images`.
 * @param {string} name File name without extension, e.g. "art5"
 * @returns {ImageEntry | null}
 */
export function getImage(name) {
  const entry = /** @type {Record<string, ImageEntry>} */ (manifest)[name];
  if (!entry && import.meta.env.DEV) {
    console.warn(
      `Image "${name}" is not in the manifest. Add it to assets-src/images and run npm run images.`,
    );
  }
  return entry ?? null;
}

/**
 * @param {string} name
 * @param {number} width
 * @param {'avif' | 'webp' | 'jpg'} format
 */
export function imageUrl(name, width, format) {
  return `${IMAGE_DIR}/${name}-${width}.${format}`;
}

/**
 * @param {string} name
 * @param {number[]} widths
 * @param {'avif' | 'webp'} format
 */
export function srcSet(name, widths, format) {
  return widths.map((width) => `${imageUrl(name, width, format)} ${width}w`).join(', ');
}
